[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$rel=$PacketPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path $full -PathType Leaf)){throw "Entity packet missing: $rel"};$p=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes((Resolve-Path $full)))|ConvertFrom-Json;foreach($x in @('EntityId','PrefabGuid','DataInfo','Parts','Owner','InitOrder','InputControl','Motion','Pool','ResourceScope','Cleanup','EvidenceRef','StaleWhen')){if($null -eq $p.PSObject.Properties[$x]){throw "Entity field missing: $x"}};if([string]$p.PrefabGuid -notmatch '^[0-9a-fA-F]{32}$'){throw 'PrefabGuid must be a 32-hex stable identity.'};if(@($p.Parts).Count -eq 0){throw 'Entity must declare owned Parts.'};if([string]$p.Cleanup -eq 'none'){throw 'Entity cleanup cannot be none.'};$ids=@{};foreach($part in @($p.Parts)){if([string]::IsNullOrWhiteSpace([string]$part)){throw 'Part identity cannot be empty.'};if($ids.ContainsKey([string]$part)){throw "Duplicate part: $part"};$ids[[string]$part]=$true};Write-Output "PASS: entity packet declares stable prefab identity, parts, ownership, lifecycle, control, motion and cleanup: $rel"
